import json

# Infer the correspondences needed for *dəpa from the supplied examples.
# Each witness gives a directly aligned Proto-Chamic and Phan Rang Cham segment.
witnesses = {
    "d": ("dilah", "talàh", 0),   # initial d → t
    "ə": ("bəsey", "pathey", 1),  # ə → a
    "p": ("paday", "patày", 0),   # p → p
    "a": ("bara", "pirà", 3),     # final a → à
}

correspondence = {}
for proto_segment, (proto_word, cham_word, index) in witnesses.items():
    correspondence[proto_segment] = cham_word[index]

target = "dəpa"
result = "".join(correspondence[segment] for segment in target)

print(json.dumps({
    "final_answer": result,
    "evidence": {
        "correspondences": ["d→t", "ə→a", "p→p", "final a→à"],
        "witnesses": ["*dilah→talàh", "*bəsey→pathey",
                      "*paday→patày", "*bara→pirà"]
    }
}, ensure_ascii=False))
